import { readFileSync, readdirSync, writeFileSync } from "node:fs";
const files = readdirSync("supabase/migrations")
  .filter((f) => f.endsWith(".sql"))
  .sort();
const body = files
  .map(
    (f) =>
      "-- " +
      f +
      "\n" +
      readFileSync("supabase/migrations/" + f, "utf8")
        .replace(/^begin;\s*$/gm, "")
        .replace(/^commit;\s*$/gm, ""),
  )
  .join("\n");
writeFileSync(
  "supabase/setup.sql",
  `-- Pond Companion: new empty project ONLY. Never run in the trading project.
-- Generated by node scripts/build-supabase-setup.mjs. One transaction: errors roll back everything.
-- If migrations were already applied, use only the unapplied migration files instead.
begin;
${body}
commit;
`,
);
